{{ config(
            materialized='table',
                post_hook={
                    "sql": "DELETE FROM `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_inventory_snapshot` WHERE snapshot_date >= DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 10 DAY); INSERT INTO `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_inventory_snapshot` WITH staged_shipmonk_products AS ( SELECT SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.id\') AS INT64) AS id, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.sku\') AS sku, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.name\') AS name, _airbyte_emitted_at AS snapshot_timestamp, DATE(_airbyte_emitted_at, \'Asia/Kolkata\') AS snapshot_date, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.created_at\') ) AS created_at, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.updated_at\') ) AS updated_at, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(SAFE.PARSE_JSON(data), \'$.inventory_on_hand_last_updated_at\') ) AS inventory_on_hand_last_updated_at, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.is_active\') AS BOOL) AS is_active, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.product_type\') AS product_type, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.hs_code\') AS hs_code, ARRAY( SELECT AS STRUCT JSON_VALUE(hs, \'$.hs_code\') AS hs_code, JSON_VALUE(hs, \'$.region\') AS region FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.hs_codes\'), [])) AS hs ) AS hs_codes, ARRAY( SELECT JSON_VALUE(barcode, \'$\') FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.barcodes\'), [])) AS barcode ) AS barcodes, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.country_code\') AS country_code, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.stock_out_days\') AS INT64) AS stock_out_days, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.replacement_cost\') AS FLOAT64) AS replacement_cost, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.replacement_cost_currency\') AS replacement_cost_currency, STRUCT( SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.weight.value\') AS FLOAT64) AS value, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.weight.unit\') AS unit ) AS weight, STRUCT( SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.dimensions.length\') AS FLOAT64) AS length, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.dimensions.width\') AS FLOAT64) AS width, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.dimensions.height\') AS FLOAT64) AS height, JSON_VALUE(SAFE.PARSE_JSON(data), \'$.dimensions.unit\') AS unit ) AS dimensions, STRUCT( SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.inventory.quantity_total_final\') AS INT64) AS quantity_total_final, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.inventory.quantity_total_available\') AS INT64) AS quantity_total_available, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.inventory.quantity_total_on_hand\') AS INT64) AS quantity_total_on_hand, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.inventory.quantity_total_quarantined\') AS INT64) AS quantity_total_quarantined, SAFE_CAST(JSON_VALUE(SAFE.PARSE_JSON(data), \'$.inventory.quantity_total_unavailable\') AS INT64) AS quantity_total_unavailable, ARRAY( SELECT AS STRUCT SAFE_CAST(JSON_VALUE(location, \'$.quantity_final\') AS INT64) AS quantity_final, SAFE_CAST(JSON_VALUE(location, \'$.quantity_available\') AS INT64) AS quantity_available, SAFE_CAST(JSON_VALUE(location, \'$.quantity_on_hand\') AS INT64) AS quantity_on_hand, SAFE_CAST(JSON_VALUE(location, \'$.quarantined_quantity\') AS INT64) AS quarantined_quantity, SAFE_CAST(JSON_VALUE(location, \'$.quantity_unavailable\') AS INT64) AS quantity_unavailable, ARRAY( SELECT AS STRUCT STRUCT( JSON_VALUE(qbl, \'$.lot.lot_number\') AS lot_number, SAFE.PARSE_TIMESTAMP( \'%Y-%m-%dT%H:%M:%E*S%Ez\', JSON_VALUE(qbl, \'$.lot.expiration_date\') ) AS expiration_date ) AS lot, SAFE_CAST(JSON_VALUE(qbl, \'$.quantity_on_hand\') AS INT64) AS quantity_on_hand FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(location, \'$.quantity_by_lot\'), [])) AS qbl ) AS quantity_by_lot, STRUCT( SAFE_CAST(JSON_VALUE(location, \'$.warehouse.id\') AS INT64) AS id, JSON_VALUE(location, \'$.warehouse.name\') AS name, JSON_VALUE(location, \'$.warehouse.identifier\') AS identifier ) AS warehouse FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.inventory.locations\'), [])) AS location ) AS locations ) AS inventory, ARRAY( SELECT AS STRUCT JSON_VALUE(bundle, \'$.bundle_sku\') AS bundle_sku, ARRAY( SELECT AS STRUCT JSON_VALUE(product, \'$.sku\') AS sku, SAFE_CAST(JSON_VALUE(product, \'$.quantity\') AS INT64) AS quantity FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(bundle, \'$.products\'), [])) AS product ) AS products FROM UNNEST(IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.product_bundles\'), [])) AS bundle ) AS product_bundles, IFNULL(JSON_QUERY_ARRAY(SAFE.PARSE_JSON(data), \'$.custom_data\'), []) AS custom_data, JSON_QUERY(SAFE.PARSE_JSON(data), \'$.product_handling_units\') AS product_handling_units, SAFE.PARSE_JSON(data) AS raw_data, _airbyte_ab_id AS source_airbyte_ab_id, _airbyte_emitted_at AS source_airbyte_emitted_at, _airbyte_normalized_at AS source_airbyte_normalized_at, _airbyte_shipmonk_get_products_for_inventory_sync_hashid AS source_airbyte_hashid, CURRENT_TIMESTAMP() AS bq_load_ts FROM `kerala-ayurveda-wh.MapleMonk.shipmonk_get_products_for_inventory_sync` WHERE DATE(_airbyte_emitted_at, \'Asia/Kolkata\') >= DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 10 DAY) ) SELECT * FROM staged_shipmonk_products; DELETE FROM `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_inventory_location_snapshot` WHERE snapshot_date >= DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 10 DAY); INSERT INTO `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_inventory_location_snapshot` WITH exploded_locations AS ( SELECT base.id, base.sku, base.name, base.snapshot_timestamp, base.snapshot_date, base.created_at, base.updated_at, base.inventory_on_hand_last_updated_at, base.is_active, base.product_type, base.hs_code, base.hs_codes, base.barcodes, base.country_code, base.stock_out_days, base.replacement_cost, base.replacement_cost_currency, base.weight, base.dimensions, location.quantity_final AS location_quantity_final, location.quantity_available AS location_quantity_available, location.quantity_on_hand AS location_quantity_on_hand, location.quarantined_quantity AS location_quarantined_quantity, location.quantity_unavailable AS location_quantity_unavailable, location.quantity_by_lot AS quantity_by_lot, location.warehouse.id AS warehouse_id, location.warehouse.name AS warehouse_name, location.warehouse.identifier AS warehouse_identifier, base.product_bundles, base.custom_data, base.product_handling_units, base.raw_data, base.source_airbyte_ab_id, base.source_airbyte_emitted_at, base.source_airbyte_normalized_at, base.source_airbyte_hashid, CURRENT_TIMESTAMP() AS bq_load_ts FROM `kerala-ayurveda-wh.MapleMonk.shipmonk_fact_inventory_snapshot` AS base CROSS JOIN UNNEST(base.inventory.locations) AS location WHERE base.snapshot_date >= DATE_SUB(CURRENT_DATE(\'Asia/Kolkata\'), INTERVAL 10 DAY) ) SELECT * FROM exploded_locations;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
